.rst-sr-only {
  clip-path: inset(50%);
  block-size: 1px;
  inline-size: 1px;
  overflow: hidden;
  position: absolute;
  white-space: nowrap;
}
.rst-sr-only:focus-visible {
  background: var(--rst-accent);
  border: 0;
  border-radius: var(--rst-radius-sm);
  block-size: auto;
  clip-path: none;
  color: var(--rst-on-accent);
  cursor: pointer;
  font: inherit;
  font-size: var(--rst-fs-sm);
  inline-size: auto;
  overflow: visible;
  padding: 0.3rem 0.6rem;
  position: static;
  white-space: normal;
}


:root {
  color-scheme: light dark;

  --rst-font: system-ui, -apple-system, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;

  --rst-radius: 6px;
  --rst-radius-sm: 4px;
  --rst-radius-pill: 999px;

  --rst-bg: light-dark(#fbfbfc, #0c0d0f);
  --rst-surface: light-dark(#ffffff, #141518);
  --rst-surface-2: light-dark(#f3f3f5, #18191d);
  --rst-line: light-dark(#e6e6ea, #26282e);
  --rst-line-strong: light-dark(#868691, #71737c);
  --rst-header-rule: var(--rst-line);

  --rst-text: light-dark(#18181b, #ededf0);
  --rst-text-muted: light-dark(#52525c, #a1a1aa);
  --rst-text-faint: light-dark(#6b6b75, #8c8c96);

  --rst-accent: light-dark(#1f56d6, #7aa2ff);
  --rst-accent-strong: light-dark(color-mix(in srgb, var(--rst-accent, #1f56d6) 80%, #000000), color-mix(in srgb, var(--rst-accent, #7aa2ff) 68.5%, #ffffff));
  --rst-accent-soft: light-dark(#ecf1ff, #16234a);
  --rst-on-accent: light-dark(#ffffff, #0c0d0f);

  --rst-tone-neutral-fg: light-dark(#374151, #c3c9d1);
  --rst-tone-neutral-bg: light-dark(#eef0f2, #262c34);
  --rst-tone-positive-fg: light-dark(#166534, #6ee7a8);
  --rst-tone-positive-bg: light-dark(#dcfce7, #10281c);
  --rst-tone-warning-fg: light-dark(#854d0e, #f0c46a);
  --rst-tone-warning-bg: light-dark(#fef3c7, #2c2110);
  --rst-tone-negative-fg: light-dark(#b91c1c, #f79aa0);
  --rst-tone-negative-bg: light-dark(#fee2e2, #331819);

  --rst-shadow-pop: 0 2px 4px light-dark(rgba(16, 24, 40, 0.06), rgba(0, 0, 0, 0.35)), 0 8px 16px -4px light-dark(rgba(16, 24, 40, 0.1), rgba(0, 0, 0, 0.5));
  --rst-shadow-knob: 0 1px 2px light-dark(rgba(16, 24, 40, 0.22), rgba(0, 0, 0, 0.5)), 0 0 0 0.5px light-dark(rgba(16, 24, 40, 0.08), rgba(0, 0, 0, 0.3));
  --rst-shadow-knob-hover: 0 1.5px 3px light-dark(rgba(16, 24, 40, 0.26), rgba(0, 0, 0, 0.58)), 0 0 0 0.5px light-dark(rgba(16, 24, 40, 0.08), rgba(0, 0, 0, 0.3));
  --rst-shadow-lift: 0 1px 2px light-dark(rgba(16, 24, 40, 0.08), rgba(0, 0, 0, 0.3));
  --rst-overlay: light-dark(rgba(0, 0, 0, 0.45), rgba(0, 0, 0, 0.6));

  --rst-accent-fill: light-dark(#2257df, #2f61e8);
  --rst-accent-fill-hover: light-dark(#1d4dc8, #2956d0);
  --rst-accent-fill-edge: light-dark(#153ca0, #1f43a6);
  --rst-accent-fill-edge-hover: light-dark(#12358f, #1a3b95);
  --rst-on-accent-fill: #ffffff;
  --rst-danger-fill: light-dark(#c62f2f, #c43232);
  --rst-danger-fill-hover: light-dark(#b12929, #af2c2c);
  --rst-danger-fill-edge: light-dark(#8d1f1f, #8c2121);
  --rst-danger-fill-edge-hover: light-dark(#7e1a1a, #7d1d1d);
  --rst-on-danger-fill: #ffffff;
  --rst-on-danger-fill-hover: #ffffff;
  --rst-danger-hover-filter: none;

  --rst-control-face: light-dark(#ffffff, #141518);
  --rst-control-face-hover: light-dark(#f7f8fa, #1b1d22);
  --rst-control-face-press: light-dark(#e6e9ee, #202329);
  --rst-control-border: light-dark(#d0d4dc, #343843);
  --rst-control-border-hover: light-dark(#8a8a95, #71737c);
  --rst-control-text-hover: light-dark(#18181b, #ededf0);
  --rst-ghost-edge: transparent;
  --rst-ghost-face-hover: light-dark(#f3f3f5, #18191d);
  --rst-ghost-edge-hover: transparent;
  --rst-summary-face: light-dark(#ffffff, #141518);
  --rst-summary-face-hover: light-dark(#f7f8fa, #1b1d22);
  --rst-summary-edge: light-dark(#d0d4dc, #343843);
  --rst-summary-edge-hover: light-dark(#8a8a95, #71737c);
  --rst-summary-radius: var(--rst-radius-sm);

  --rst-depth-hl: light-dark(rgba(255, 255, 255, 0.8), rgba(255, 255, 255, 0.06));
  --rst-depth-contact: light-dark(rgba(16, 24, 40, 0.1), rgba(0, 0, 0, 0.5));
  --rst-depth-ambient: light-dark(rgba(16, 24, 40, 0.06), rgba(0, 0, 0, 0.35));
  --rst-depth-face: 0.04;
  --rst-press-drop: 1px;

  --rst-knob: #ffffff;
  --rst-knob-shade: light-dark(#f1f3f6, #d9dee8);
  --rst-track-off: light-dark(#8a8a95, #71737c);
  --rst-switch-w: 40px;
  --rst-switch-h: 23px;
  --rst-switch-knob: 19px;
  --rst-switch-touch-w: 51px;
  --rst-switch-touch-h: 31px;
  --rst-switch-touch-knob: 27px;

  --rst-tint-hover: light-dark(color-mix(in srgb, var(--rst-accent, #1f56d6) 4.5%, var(--rst-surface)), color-mix(in srgb, var(--rst-accent, #7aa2ff) 10%, var(--rst-bg)));
  --rst-tint-press: light-dark(color-mix(in srgb, var(--rst-accent, #1f56d6) 8.5%, var(--rst-surface)), color-mix(in srgb, var(--rst-accent, #7aa2ff) 19%, #000000));
  --rst-tint-tap: var(--rst-tint-press);
  --rst-tint-card-hover: var(--rst-tint-hover);
  --rst-tint-tile-hover: var(--rst-tint-hover);
  --rst-tint-tile-press: var(--rst-tint-press);
  --rst-tint-group-hover: var(--rst-tint-hover);
  --rst-row-tint-hover: var(--rst-tint-hover);
  --rst-row-tint-press: var(--rst-tint-press);
  --rst-focus-edge: var(--rst-accent, light-dark(#1f56d6, #7aa2ff));
  --rst-focus-halo: color-mix(in srgb, var(--rst-accent, light-dark(#1f56d6, #7aa2ff)) 22%, transparent);

  --rst-sheen-fill: light-dark(rgba(255, 255, 255, 0.08), rgba(255, 255, 255, 0.04));
  --rst-sheen-plain: light-dark(color-mix(in srgb, var(--rst-accent-fill) 9%, transparent), rgba(255, 255, 255, 0.04));
  --rst-light-rim: light-dark(color-mix(in srgb, var(--rst-accent, #1f56d6) 23%, var(--rst-line)), color-mix(in srgb, var(--rst-accent, #7aa2ff) 31%, #505050));
  --rst-light-wash: light-dark(rgba(255, 255, 255, 0), rgba(255, 255, 255, 0.015));

  --rst-press-wash: 0.08;
  --rst-press-spot: 0.16;
  --rst-press-wash-plain: 0.04;
  --rst-press-spot-plain: 0.07;

  --rst-title-size: 1.25rem;
  --rst-title-weight: 600;
  --rst-title-track: -0.012em;
  --rst-heading-size: 0.8125rem;
  --rst-label-case: none;
  --rst-label-track: 0;
  --rst-rail-bg: var(--rst-bg);
  --rst-nav-current-bg: light-dark(#ffffff, #141518);
  --rst-nav-current-fg: light-dark(#18181b, #ededf0);
}

@supports (color: oklch(from red l c h)) {
  :root {
    --rst-accent-soft: light-dark(oklch(from var(--rst-accent, #1f56d6) 0.958 min(calc(c * 0.0878), 0.018) h), oklch(from var(--rst-accent, #7aa2ff) 0.268 min(calc(c * 0.5039), 0.072) h));
    --rst-accent-fill: light-dark(oklch(from var(--rst-accent, #1f56d6) calc(0.513 - 0.05 * max(0, cos((h - 170) * 1deg) - 0.087)) min(calc(c * 1.0244), 0.21) h), oklch(from var(--rst-accent, #7aa2ff) calc(0.543 - 0.1 * max(0, cos((h - 170) * 1deg) - 0.087)) min(calc(c * 1.5045), 0.215) h));
    --rst-accent-fill-hover: light-dark(oklch(from var(--rst-accent, #1f56d6) calc(0.472 - 0.045 * max(0, cos((h - 170) * 1deg) - 0.087)) min(calc(c * 0.9463), 0.194) h), oklch(from var(--rst-accent, #7aa2ff) calc(0.5 - 0.05 * max(0, cos((h - 170) * 1deg) - 0.087)) min(calc(c * 1.3786), 0.197) h));
    --rst-accent-fill-edge: light-dark(oklch(from var(--rst-accent, #1f56d6) 0.401 min(calc(c * 0.8049), 0.165) h), oklch(from var(--rst-accent, #7aa2ff) 0.422 min(calc(c * 1.1617), 0.166) h));
    --rst-accent-fill-edge-hover: light-dark(oklch(from var(--rst-accent, #1f56d6) 0.37 min(calc(c * 0.7366), 0.151) h), oklch(from var(--rst-accent, #7aa2ff) 0.389 min(calc(c * 1.0847), 0.155) h));
  }
}

:root[data-theme="light"] { color-scheme: light; }
:root[data-theme="dark"] { color-scheme: dark; }

:root[data-theme="dark"] { --rst-press-wash: 0.18; --rst-press-spot: 0.30; --rst-press-wash-plain: 0.18; --rst-press-spot-plain: 0.30; }
@media (prefers-color-scheme: dark) { :root:not([data-theme="light"]) { --rst-press-wash: 0.18; --rst-press-spot: 0.30; --rst-press-wash-plain: 0.18; --rst-press-spot-plain: 0.30; } }
